"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[8916],{9362(a){a.exports=JSON.parse('{"title":"Outer margin\uc740 \uc548\ud2f0 \ud328\ud134\uc774\ub2e4.","date":"2024-03-13","coverUrl":null,"html":"<h2 data-notion-block-id=\\"2a42b973-0761-40a4-af3b-e8c1fe598c98\\" id=\\"2a42b973-0761-40a4-af3b-e8c1fe598c98\\">Outer margin\uc740 \uc548\ud2f0 \ud328\ud134\uc774\ub2e4.</h2><a href=\\"https://kyleshevlin.com/no-outer-margin/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kyleshevlin.com/no-outer-margin/</a><p data-notion-block-id=\\"91079137-abe7-483b-8d77-b65c6747cb2a\\"><b>\uc2ec\uc724\uc12d</b>: \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4 \uacbd\uc6b0 \ucef4\ud3ec\ub10c\ud2b8\uc5d0\uc11c Outer margin\uc744 \uc124\uc815\ud558\ub294 \uac83\uc740 \uc548\ud2f0 \ud328\ud134\uc774 \ub41c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. Flex, Grid\ub97c \ub9ce\uc774 \uc4f0\ub294 \ubaa8\ub358 CSS\uc5d0\uc11c margin\uc744 \ucef4\ud3ec\ub10c\ud2b8\uc758 \ucd5c\uc0c1\ub2e8 \uc694\uc18c\uc5d0 \ub123\uac8c \ub418\uba74 \uc7ac\uc0ac\uc6a9\uc131\uc774 \uc5b4\ub824\uc6cc\uc9c4\ub2e4\ub294 \ub9d0\uc744 \ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub294 \uae30\ubcf8 CSS\ub97c \uc5c6\uc560 \ube60\ub978 \ub9c8\ud06c\uc5c5\uc744 \ubc29\ud574\ud558\uac70\ub098 \uae30\ubcf8 <code>display</code>\uc18d\uc131\uc774 \uc544\ub2d0\uacbd\uc6b0\uc758 CSS\ub97c \ub530\ub85c \ub300\uc751\ud574\uc57c \ud558\ubbc0\ub85c \uc7a5\ub2e8\uc810\uc744 \uc0dd\uac01\ud574\uc11c \uc801\uc6a9\ud558\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"077420b0-300b-4eec-b81f-8f2780b75ae8\\" id=\\"077420b0-300b-4eec-b81f-8f2780b75ae8\\">CSS \ud37c\ud3ec\uba3c\uc2a4 \ud5a5\uc0c1\uc744 \uc704\ud574 \ud574\uc57c\ud560 \uc77c</h2><a href=\\"https://nolanlawson.com/2023/01/17/my-talk-on-css-runtime-performance/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nolanlawson.com/2023/01/17/my-talk-on-css-runtime-performance/</a><p data-notion-block-id=\\"eef0fbf8-fa6a-46d1-b5d9-da86b096feb9\\"><b>\uc2ec\uc724\uc12d</b>: \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1 \uacfc\uc815\uc744 \uc124\uba85\ud558\uba74\uc11c \uadf8 \uacfc\uc815\uc5d0\uc11c \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ucd5c\uc801\ud654\ub97c \uc5b4\ub5bb\uac8c \ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \ud53c\ud574\uc57c \ud560 \ud328\ud134\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \uac00\uc7a5 \uac15\uc870\ud558\ub294 \uac83\uc740 scoped style\uc744 \uc0ac\uc6a9\ud558\uace0 \ub108\ubb34 \ub9ce\uc740 \uc120\ud0dd\uc790\ub97c \ud53c\ud558\uba74 \uc131\ub2a5\uc744 \ud5a5\uc0c1\ud560 \uc218 \uc788\ub2e4\uace0 \uc870\uc5b8\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5ed\uc2dc \uc131\uae09\ud55c \ucd5c\uc801\ud654\ub97c \uc704\ud574 \uc0c8\ub85c\uc6b4 CSS \uae30\ub2a5\uc744 \ud53c\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \ub9d0\ub3c4 \ucca8\uac00\ud588\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c\ub294 CSS \ub80c\ub354\ub9c1\uacfc JS\uc758 \uacc4\uc0b0\uc744 \uc800\uc6b8\uc9c8\ud558\ub294 \uac83\uc774 \uc6b0\uc120\ub418\uc5b4\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"0b9c35b6-1404-4202-8788-b05d18ef16e5\\" id=\\"0b9c35b6-1404-4202-8788-b05d18ef16e5\\">TypeScript\uc758 \ud0c0\uc785 \uc608\uce21\uc758 \uc228\uaca8\uc9c4 \ubd80\ubd84</h2><a href=\\"https://effectivetypescript.com/2024/02/27/type-guards/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://effectivetypescript.com/2024/02/27/type-guards/</a><p data-notion-block-id=\\"6f578221-8fca-47f9-abd3-bd98a492622f\\"><b>\uc2ec\uc724\uc12d</b>: \uc0ac\uc6a9\uc790 \uc815\uc758 \ud0c0\uc785 \uac00\ub4dc\ub294 <code>as unknown as A</code>\uc640 \uac19\uc740 \ud6a8\uacfc\ub97c \uac00\uc9c0\uace0 \uc788\uc73c\uba70 \ub0b4\ubd80 \uad6c\ud604\uacfc \ub9e4\uac1c\ubcc0\uc218 \uac12\uc744 \uc124\uc815\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\ub9ac\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud639\uc740 \ud14c\uc2a4\ud2b8\ub97c \ud1b5\ud574\uc11c \uc548\uc815\uc801\uc774\uac8c \uc0ac\uc6a9\ud560 \uc218\ub3c4 \uc788\uad6c\uc694.</p><h2 data-notion-block-id=\\"ad17f4c6-6613-497a-8311-585a1180ae57\\" id=\\"ad17f4c6-6613-497a-8311-585a1180ae57\\">\uc2dc\uac01\uc801 \ud14c\uc2a4\ud2b8 \ud29c\ud1a0\ub9ac\uc5bc</h2><a href=\\"https://www.browsercat.com/post/ultimate-guide-visual-testing-playwright\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.browsercat.com/post/ultimate-guide-visual-testing-playwright</a><p data-notion-block-id=\\"188465a9-e08d-4ba8-9bd0-9859063f7bee\\"><b>\uc2ec\uc724\uc12d</b>: \uc2dc\uac01\uc801 \ud14c\uc2a4\ud2b8\ub294 \uac15\ub825\ud558\uc9c0\ub9cc \uc2dc\uc791\ud558\uae30\uc5d0 \ub9e4\uc6b0 \ud798\ub4e7\ub2c8\ub2e4(\uc124\uc815\ud560 \uac83\uc774 \ub9ce\uc74c). \uadf8\uac83\uc744 Playwright\ub97c \ud1b5\ud574\uc11c \uc124\uc815\ud558\uace0 \uace0\uae09 \uae30\ubc95\uc744 \ubc30\uc6b0\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://fe-developers.kakaoent.com/2023/230223-backstopjs-vrt/\\">\uce74\uce74\uc624 \uc5d4\ud130\ud504\ub77c\uc774\uc988\uc5d0\uc11c BackstopJS\ub97c \uc801\uc6a9\ud55c \ube14\ub85c\uadf8</a>\ub3c4 \uc788\uc73c\ub2c8 \ucc38\uace0\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6ec17ca3-9985-48f9-a9a9-7cb9706d11eb\\" id=\\"6ec17ca3-9985-48f9-a9a9-7cb9706d11eb\\">CSS \uc2e0\uae30\ub2a5\uc744 \ud1b5\ud55c JS\uc5c6\uc774 \uc2a4\ud06c\ub864 \uc560\ub2c8\uba54\uc774\uc158 \uad6c\ud604</h2><a href=\\"https://ryanmulligan.dev/blog/scroll-triggered-animations-style-queries/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ryanmulligan.dev/blog/scroll-triggered-animations-style-queries/</a><p data-notion-block-id=\\"8881f5a0-eb1a-4276-b52d-60dff02f9c7f\\"><b>\uc2ec\uc724\uc12d</b>: \ud3b8\uc758\uc131 \ubd80\ubd84\uc5d0\uc11c \uac1c\uc120\ub418\uc5b4 \uc81c\uacf5\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc88b\uc744 \uc218\ub3c4 \uc788\uaca0\ub124\uc694. \ubb3c\ub860 \ud3f4\ub9ac\ud544\uc5d0\uc11c \uc9c0\uc625\uc744 \uacbd\ud5d8\ud560 \ub4ef\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6625f4d3-4c19-48e3-9ba2-04abb2a76adf\\" id=\\"6625f4d3-4c19-48e3-9ba2-04abb2a76adf\\"><b><code>useSyncExternalStore</code></b><b>\ub85c hydration \ubd88\uc77c\uce58 \ubc29\uc9c0</b></h2><a href=\\"https://tkdodo.eu/blog/avoiding-hydration-mismatches-with-use-sync-external-store\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/avoiding-hydration-mismatches-with-use-sync-external-store</a><p data-notion-block-id=\\"763b8278-0d01-4223-a59d-9157b0397d1d\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787\\">1\uc6d4 \ub274\uc2a4\ub808\ud130\uc5d0\uc11c</a> \ub3d9\uc2dc\uc131\uc744 \ub2e4\ub8e8\uba74\uc11c \ub098\uc628(React\uc5d0\uc11c \uc0c1\ud0dc \ubd88\uc77c\uce58 \ucc38\uc870) <code>useSyncExternalStore</code>\uc5d0 \ub300\ud55c \uc774\uc57c\uae30 \uc785\ub2c8\ub2e4. Hydration \ubd88\uc77c\uce58\ub97c \uc904\uc5ec Layout Shift\ub97c \uc904\uc774\uc790\ub294 \uc774\uc57c\uae30\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774\uc804 \ub274\uc2a4\ub808\ud130 \uae30\uc0ac\uc5d0\uc11c\ub3c4 \ub2e4\ub918\ub4ef\uc774 \ub3d9\uc2dc\uc131 \uc774\uc810\uc744 \uc783\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc810\ub3c4 \uace0\ub824\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"68438377-f4d8-49a1-83ed-d11c7aeab6c9\\" id=\\"68438377-f4d8-49a1-83ed-d11c7aeab6c9\\">Gastby\uc5d0 \ub300\ud55c \ud68c\uace0</h2><a href=\\"https://www.smashingmagazine.com/2024/03/end-of-gatsby-journey/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2024/03/end-of-gatsby-journey/</a><p data-notion-block-id=\\"f838dbd9-c28e-4a32-a3b9-9c99668f6d1e\\"><b>\uc2ec\uc724\uc12d</b>: Gatsby\uc758 SSG\uc5d0 \ub300\ud55c \uc811\uadfc \ubc29\uc2dd\uc740 \uc88b\uc558\uc73c\ub098 \uc218\uc775\ucc3d\ucd9c \ubc29\uc2dd\uc744 \ud480\uc5b4\ub0c4\uacfc DX\uc758 \uc544\uc26c\uc6c0\uc744 \ud574\uacb0\ud558\uc9c0 \uc54a\uc74c\uc5d0 \ub300\ud55c \uc798\ubabb\uc744 \ud68c\uace0\ud569\ub2c8\ub2e4. \ubaa8\ub4e0 \ud504\ub808\uc784\uc6cc\ud06c\ub294 \uc6a9\ub3c4\uc5d0 \ub530\ub77c \ub3c4\uc6c0\uc774 \ub418\uace0, \uadf8\ub3d9\uc548 \uc368\uc654\ub358 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ud3ec\uae30\ud558\ub294 \uac83\uc740 \uae30\ud68c\ube44\uc6a9\uc77c \uc218\ub3c4 \uc788\ub2e4\ub294 \uc800\uc790\uc758 \ub9d0\uc744 \uac15\uc870\ud558\uace0 \uc2f6\ub124\uc694.</p><h2 data-notion-block-id=\\"078f8736-c470-405a-a491-4f3d748c59b9\\" id=\\"078f8736-c470-405a-a491-4f3d748c59b9\\">\uadf8\ub7fc\uc5d0\ub3c4 RSC\ub294 \ub098\uc544\uac00\uc57c \ud55c\ub2e4.</h2><a href=\\"https://www.builder.io/blog/why-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/why-react-server-components</a><p data-notion-block-id=\\"3285a902-c8cf-4c6d-a8e2-8a27f9250366\\"><b>\uc2ec\uc724\uc12d</b>: React\uc758 \uc11c\ubc84\ucef4\ud3ec\ub10c\ud2b8\uac00 \uc5b4\ub5bb\uac8c \ub098\uc624\uac8c \ub418\uc5c8\ub294\uc9c0\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4. \uc5b4\ub5bb\uac8c \ub098\uc624\uac8c \ub418\uc5c8\ub098 \uc5ed\uc0ac\uac00 \uad81\uae08\ud558\uba74 \uc77d\uc5b4\ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"97d84323-de8e-47ea-8fa6-fb87e9d67bec\\" id=\\"97d84323-de8e-47ea-8fa6-fb87e9d67bec\\">Shopify\uc758 \uc571 \ub80c\ub354\ub9c1 \ucd5c\uc801\ud654</h2><a href=\\"https://shopify.engineering/improving-shopify-app-s-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopify.engineering/improving-shopify-app-s-performance</a><p data-notion-block-id=\\"936a77cc-c353-4e39-b679-203477fc2943\\"><b>\uc2ec\uc724\uc12d</b>: \uc571\uc774\ub77c\uace0 \uc368\ub1a8\uc9c0\ub9cc \uc6f9\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \ubd80\ubd84\uc774\uae30 \ub54c\ubb38\uc5d0 \uc77d\uace0 \ud55c \ubc88 \uc0dd\uac01\ud574\ubcfc \ub9cc\ud55c \uae00\ub85c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"e8e18354-ce86-467a-bf12-10fbb31a4368\\"></p>"}')}}]);